// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, interpolateColors } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadKalam = makeLoadFont('Kalam');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: kalamFamily } = loadKalam();



export type ChapterAnimationProps = Record<string, any>;

const ChapterAnimation: React.FC<ChapterAnimationProps> = ({
  backgroundColor = "#f9f9f9",
  transparentBackground = false,
  durationInSeconds = 15,
  headingColor = "#2d2d2d",
  primaryColor = "#f97316",
  chapters = [
    { label: "1", text: "THE BEGINNING OF THE END" },
    { label: "2", text: "DISCOVERING THE PROBLEM" },
    { label: "3", text: "PEOPLE DON'T BUY PRODUCTS THEY BUY" },
    { label: "4", text: "UNDERSTANDING THE SOLUTION" },
    { label: "5", text: "IMPLEMENTING THE STRATEGY" },
    { label: "6", text: "THE FINAL OUTCOME" }
  ]
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const parsedBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  if (!chapters || chapters.length === 0) {
    return null;
  }

  // Calculate timing per chapter
  const framesPerChapter = Math.max(1, Math.floor((durationInSeconds * fps) / chapters.length));
  
  // Guard against out of bounds if frame exceeds expected total duration
  const safeFrame = Math.min(frame, chapters.length * framesPerChapter - 1);
  const currentChapterIndex = Math.min(chapters.length - 1, Math.floor(safeFrame / framesPerChapter));
  const localFrame = safeFrame - currentChapterIndex * framesPerChapter;

  // Determine exit animations for the current chapter before the next one starts
  const exitDuration = Math.min(15, Math.floor(framesPerChapter / 3));
  const isExiting = localFrame > framesPerChapter - exitDuration && currentChapterIndex < chapters.length - 1;
  const exitProgress = isExiting 
    ? interpolate(localFrame, [framesPerChapter - exitDuration, framesPerChapter], [0, 1], { extrapolateRight: 'clamp' }) 
    : 0;

  // Heading Animation
  const headingSpring = spring({ frame: localFrame, fps, config: { damping: 14 } });
  const headingOpacity = interpolate(localFrame, [0, 10], [0, 1], { extrapolateRight: 'clamp' });
  const headingTranslateY = interpolate(headingSpring, [0, 1], [30, 0]);
  const finalHeadingOpacity = interpolate(exitProgress, [0, 1], [headingOpacity, 0]);
  const finalHeadingTranslateY = headingTranslateY - interpolate(exitProgress, [0, 1], [0, 30]);

  // Middle Text Animation (Staggered by 5 frames)
  const textSpring = spring({ frame: Math.max(0, localFrame - 5), fps, config: { damping: 14 } });
  const textOpacity = interpolate(localFrame - 5, [0, 10], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const textScale = interpolate(textSpring, [0, 1], [0.95, 1]);
  const finalTextOpacity = interpolate(exitProgress, [0, 1], [textOpacity, 0]);
  const finalTextScale = textScale - interpolate(exitProgress, [0, 1], [0, 0.05]);

  // Global Progress Bar Entry Animation
  const progressBarSpring = spring({ frame, fps, config: { damping: 15 } });
  const progressBarTranslateY = interpolate(progressBarSpring, [0, 1], [50, 0]);
  const progressBarOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: 'clamp' });

  return (
    <AbsoluteFill style={{ backgroundColor: parsedBgColor, fontFamily: interFamily }}>
      <div style={{ 
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'center', 
        justifyContent: 'center', 
        width: '100%', 
        height: '100%', 
        padding: '0 5%' 
      }}>
        
        {/* Top Heading */}
        <div style={{
          opacity: finalHeadingOpacity,
          transform: `translateY(${finalHeadingTranslateY}px)`,
          display: 'inline-flex',
          flexDirection: 'column',
          alignItems: 'center',
          marginBottom: 80,
          transition: "none"
        }}>
          <div style={{ 
            fontSize: 130, 
            fontWeight: 900, 
            color: headingColor, 
            textTransform: 'uppercase', 
            letterSpacing: '-0.02em', 
            lineHeight: 1 
          }}>
            CHAPTER {chapters[currentChapterIndex].label}
          </div>
          <div style={{ 
            width: '100%', 
            height: 12, 
            backgroundColor: headingColor, 
            marginTop: 15 
          }} />
        </div>

        {/* Middle Text */}
        <div style={{
          fontFamily: kalamFamily,
          fontSize: 90,
          fontWeight: 'bold',
          color: primaryColor,
          textAlign: 'center',
          maxWidth: '85%',
          height: 250,
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          opacity: finalTextOpacity,
          transform: `scale(${finalTextScale})`,
          lineHeight: 1.2,
          textTransform: 'uppercase',
          marginBottom: 80,
          transition: "none"
        }}>
          {chapters[currentChapterIndex].text}
        </div>

        {/* Progress Bar */}
        <div style={{
           position: 'relative',
           width: '90%',
           maxWidth: 1400,
           height: 100,
           display: 'flex',
           alignItems: 'center',
           justifyContent: 'space-between',
           opacity: progressBarOpacity,
           transform: `translateY(${progressBarTranslateY}px)`,
           transition: "none"
        }}>
          {/* Background connecting line */}
          <div style={{ 
            position: 'absolute', 
            width: '100%', 
            height: 8, 
            backgroundColor: headingColor, 
            zIndex: 1 
          }} />
          
          {/* Progress Circles */}
          {chapters.map((ch, i) => {
            const localStartFrame = i * framesPerChapter;
            const localEndFrame = (i + 1) * framesPerChapter;
            
            let circleScale = 1;
            let circleBgOpacity = 0;
            
            if (safeFrame >= localStartFrame && safeFrame < localEndFrame) {
              // Circle is currently active
              const activeFrame = safeFrame - localStartFrame;
              const pop = spring({ frame: activeFrame, fps, config: { damping: 12 } });
              circleScale = interpolate(pop, [0, 1], [1, 1.15]);
              circleBgOpacity = pop;
            } else if (safeFrame >= localEndFrame) {
              // Circle is in the past, un-pop and crossfade back to inactive colors
              const outFrame = safeFrame - localEndFrame;
              const unpop = spring({ frame: outFrame, fps, config: { damping: 12 } });
              circleScale = interpolate(unpop, [0, 1], [1.15, 1]);
              circleBgOpacity = interpolate(unpop, [0, 1], [1, 0]);
            }

            const circleFillColor = interpolateColors(circleBgOpacity, [0, 1], ["#ffffff", primaryColor]);
            const circleTextColor = interpolateColors(circleBgOpacity, [0, 1], [headingColor, "#ffffff"]);
            
            return (
              <div key={i} style={{
                width: 90, 
                height: 90,
                borderRadius: 45,
                backgroundColor: circleFillColor,
                border: `6px solid ${headingColor}`,
                color: circleTextColor,
                display: 'flex', 
                justifyContent: 'center', 
                alignItems: 'center',
                fontSize: 45, 
                fontWeight: 900,
                transform: `scale(${circleScale})`,
                zIndex: 2,
                boxSizing: 'border-box',
                transition: "none"
              }}>
                {ch.label}
              </div>
            )
          })}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default ChapterAnimation;